      "path": "package.json",
      "content": "{\n  \"name\": \"voyager\",\n  \"version\": \"2.3.1\",\n  \"description\": \"A better workspace for Gemini, Claude, ChatGPT, and DeepSeek: prompts, reading tools, organization, export, and more.\",\n  \"packageManager\": \"bun@1.3.12\",\n  \"license\": \"GPL-3.0\",\n  \"author\": \"Jesse Zhang\",\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/voyager-crew/voyager.git\"\n  },\n  \"scripts\": {\n    \"bump\": \"bun scripts/bump-version.js\",\n    \"build\": \"vite build --config vite.config.chrome.ts\",\n    \"build:chrome\": \"vite build --config vite.config.chrome.ts\",\n    \"build:edge\": \"bun scripts/build-edge.js\",\n    \"build:firefox\": \"vite build --config vite.config.firefox.ts\",\n    \"build:safari\": \"vite build --config vite.config.safari.ts && node scripts/verify-safari-resources.mjs\",\n    \"build:all\": \"bun run build:chrome && bun run build:firefox && bun run build:safari\",\n    \"build:browsers\": \"bun run build:all && bun run build:edge\",\n    \"dev\": \"nodemon --config nodemon.chrome.json\",\n    \"dev:chrome\": \"nodemon --config nodemon.chrome.json\",\n    \"dev:chrome-open\": \"bun scripts/launch-chrome.cjs\",\n    \"dev:firefox\": \"nodemon --config nodemon.firefox.json\",\n    \"dev:safari\": \"nodemon --config nodemon.safari.json\",\n    \"test\": \"vitest run\",\n    \"test:ui\": \"vitest --ui\",\n    \"test:coverage\": \"vitest run --coverage\",\n    \"test:changed\": \"node scripts/test-changed.mjs\",\n    \"test:watch\": \"vitest watch\",\n    \"lint\": \"oxlint --fix\",\n    \"lint:check\": \"oxlint\",\n    \"format\": \"oxfmt\",\n    \"format:check\": \"oxfmt --check\",\n    \"clean:build\": \"find .build -mindepth 1 -maxdepth 1 ! -name sparkle-source-packages -exec rm -rf {} + && echo 'Cleared Xcode derived data (kept .build/sparkle-source-packages).'\",\n    \"i18n:check\": \"node scripts/check-locale-keys.mjs\",\n    \"bench:folders\": \"bun bench/folders/run.ts\",\n    \"bench:check\": \"tsc -p bench/folders --noEmit && bun bench/folders/check.ts\",\n    \"filesize:check\": \"node scripts/check-file-size.mjs\",\n    \"filesize:update\": \"node scripts/check-file-size.mjs --update\",\n    \"typecheck\": \"tsc --noEmit\",\n    \"verify:pr\": \"bun run format:check && bun run lint:check && bun run typecheck && bun run bench:check && bun run i18n:check && bun run filesize:check && bun run plugin:check && bun run selectors:check && bun run site-knowledge:check && bun run panel:check && bun run test && bun run build:all && bun run cli:build && bun run docs:build\",\n    \"verify:katex-export\": \"bun scripts/verify-katex-export.ts\",\n    \"commitlint\": \"commitlint --edit $GIT_PARAMS\",\n    \"catalog:build\": \"bun scripts/build-plugin-catalog.ts\",\n    \"cli:build\": \"bun packages/create-voyager-plugin/build.ts\",\n    \"skills:build\": \"bun run cli:build && node packages/create-voyager-plugin/dist/cli.mjs skill --out docs/public/skills/write-voyager-plugin\",\n    \"plugin:new\": \"bun scripts/plugin-new.ts\",\n    \"selectors:check\": \"bun scripts/check-locator-contracts.ts\",\n    \"panel:check\": \"bun scripts/check-panel-apis.ts\",\n    \"site-knowledge:check\": \"bun scripts/check-site-knowledge.ts\",\n    \"plugin:check\": \"bun scripts/plugin-check.ts\",\n    \"plugin:release:check\": \"bun scripts/plugin-release-check.ts\",\n    \"docs:dev\": \"vitepress dev docs\",\n    \"docs:build\": \"vitepress build docs\",\n    \"docs:preview\": \"vitepress preview docs\",\n    \"sponsors:update\": \"bun run scripts/generate-sponsors.cjs\",\n    \"hooks:install\": \"node scripts/install-git-hooks.cjs\",\n    \"prepare\": \"node scripts/install-git-hooks.cjs\"\n  },\n  \"type\": \"module\",\n  \"dependencies\": {\n    \"@floating-ui/dom\": \"1.8.0\",\n    \"@headless-tree/core\": \"1.7.0\",\n    \"@tanstack/virtual-core\": \"3.17.11\",\n    \"class-variance-authority\": \"^0.7.1\",\n    \"clsx\": \"^2.1.1\",\n    \"dompurify\": \"^3\",\n    \"echarts\": \"6.1.0\",\n    \"html-to-image\": \"^1.11.13\",\n    \"json5\": \"^2.2.3\",\n    \"katex\": \"^0.16\",\n    \"lucide-react\": \"^0.553.0\",\n    \"marked\": \"16.4.1\",\n    \"marked-katex-extension\": \"^4\",\n    \"mermaid\": \"11.12.2\",\n    \"mermaid-legacy\": \"npm:mermaid@9.2.2\",\n    \"onml\": \"^2.1.0\",\n    \"preact\": \"10.27.3\",\n    \"react\": \"^19.1.0\",\n    \"react-dom\": \"^19.1.0\",\n    \"tailwind-merge\": \"^3.3.1\",\n    \"temml\": \"^0.13.1\",\n    \"wavedrom\": \"3.6.2\",\n    \"webextension-polyfill\": \"^0.12.0\"\n  },\n  \"devDependencies\": {\n    \"@crxjs/vite-plugin\": \"2.2.1\",\n    \"@nolebase/vitepress-plugin-git-changelog\": \"^2.18.2\",\n    \"@tailwindcss/vite\": \"^4.1.15\",\n    \"@types/chrome\": \"^0.1.24\",\n    \"@types/jsdom\": \"^27.0.0\",\n    \"@types/jszip\": \"^3.4.1\",\n    \"@types/node\": \"^24.9.0\",\n    \"@types/react\": \"^19.2.2\",\n    \"@types/react-dom\": \"^19.2.2\",\n    \"@types/webextension-polyfill\": \"^0.12.3\",\n    \"@vitejs/plugin-react\": \"5.1.0\",\n    \"@vitest/coverage-v8\": \"^5.0.3\",\n    \"@vitest/ui\": \"^5.0.3\",\n    \"chrome-webstore-upload-cli\": \"3.5.0\",\n    \"esbuild\": \"0.25.11\",\n    \"fs-extra\": \"^11.3.0\",\n    \"jsdom\": \"^27.1.0\",\n    \"jszip\": \"^3.10.1\",\n    \"nodemon\": \"^3.1.10\",\n    \"oxfmt\": \"^0.65.0\",\n    \"oxlint\": \"^1.80.0\",\n    \"tailwindcss\": \"^4.1.15\",\n    \"ts-node\": \"^10.9.2\",\n    \"typescript\": \"^5.8.3\",\n    \"vite\": \"^7.1.11\",\n    \"vite-tsconfig-paths\": \"^5.1.4\",\n    \"vitepress\": \"^1.6.4\",\n    \"vitest\": \"^5.0.3\",\n    \"vue\": \"^3.5.24\",\n    \"vue3-marquee\": \"^4.2.2\",\n    \"web-ext\": \"10.5.0\",\n    \"web-ext-run\": \"^0.2.4\"\n  },\n  \"overrides\": {\n    \"rollup\": \"^4.24.0\"\n  }\n}\n"
