   \"css\": [\"contentStyle.css\"]\n    },\n    {\n      \"matches\": [\n        \"https://gemini.google.com/*\",\n        \"https://business.gemini.google/*\",\n        \"https://aistudio.google.com/*\",\n        \"https://aistudio.google.cn/*\"\n      ],\n      \"js\": [\"src/pages/content/shadowKeyGuardEntry.ts\"],\n      \"run_at\": \"document_start\"\n    },\n    {\n      \"matches\": [\"https://gemini.google.com/*\", \"https://business.gemini.google/*\"],\n      \"js\": [\"src/pages/content/usageObserverLoader.ts\"],\n      \"run_at\": \"document_start\"\n    }\n  ],\n  \"web_accessible_resources\": [\n    {\n      \"resources\": [\n        \"src/pages/panel/index.html\",\n        \"contentStyle.css\",\n        \"changelog-activity-view.png\",\n        \"watermark-native-steps.png\",\n        \"icon-128.png\",\n        \"icon-32.png\",\n        \"mascot-logo.png\",\n        \"katex-config.js\",\n        \"fetchInterceptor.js\",\n        \"claude-usage-observer.js\",\n        \"response-complete-observer.js\",\n        \"usage-observer.js\",\n        \"conversation-history-observer.js\",\n        \"prevent-auto-scroll.js\",\n        \"assets/*.js\",\n        \"assets/katex*.css\",\n        \"assets/KaTeX_*\",\n        \"assets/*.png\"\n      ],\n      \"matches\": [\"<all_urls>\"]\n    },\n    {\n      \"resources\": [\"src/pages/mermaidRenderer/index.html\"],\n      \"matches\": [\"<all_urls>\"]\n    }\n  ]\n}\n"
